// HMAC signature verification (plan section 20, T9: "Unauthenticated n8n
webhook" -> "HMAC signature required; replay window; rejected calls
logged"). This is deliberately in a Code node, not left unverified --
signature checking is trivial logic that belongs in the workflow, unlike
everything desk/api.py itself does (parsing, crypto, custody, grounding),
which must never move into n8n. See n8n/README.md.

Expects header 'x-desk-signature' = hex HMAC-SHA256 of the raw JSON body
using a secret shared with this workflow's own configuration (set via an
n8n environment variable, DESK_WEBHOOK_SECRET -- never hard-coded here).

n8n's Code node has no built-in crypto module access by default in some
deployments; where it is unavailable, verification should be delegated to
a Function node backed by n8n's built-in 'crypto' helper or moved to an
upstream reverse proxy. That deployment-specific choice is why this node
is intentionally small and isolated -- swap it without touching anything
downstream.
const crypto = require('crypto');

const secret = $env.DESK_WEBHOOK_SECRET;
if (!secret) {
  throw new Error('DESK_WEBHOOK_SECRET is not set -- refusing to accept an unverifiable webhook');
}

const signatureHeader = $input.item.json.headers['x-desk-signature'];
if (!signatureHeader) {
  throw new Error('missing x-desk-signature header');
}

const rawBody = JSON.stringify($input.item.json.body);
const expected = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');

// Constant-time compare -- a naive === here would leak timing information
// about how many leading bytes matched.
const a = Buffer.from(signatureHeader, 'utf8');
const b = Buffer.from(expected, 'utf8');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('signature mismatch -- rejecting');
}

return [{ json: $input.item.json.body }];

